<?php declare(strict_types=1);$permissions=$data['user']['permissions']??[];$canManage=in_array('assets.manage',$permissions,true);$canCapitalize=in_array('assets.inventory.capitalize',$permissions,true);$hasCategories=!empty($data['categories']);$money=static fn($v,$c)=>$c.' '.number_format((float)$v,2);$section=(string)($_GET['section']??'register');if(!in_array($section,['register','direct','categories','capitalization'],true))$section='register';$query=trim((string)($_GET['q']??''));$visibleAssets=$query===''?$data['assets']:array_values(array_filter($data['assets'],static fn($asset):bool=>str_contains(strtolower((string)$asset['asset_number'].' '.(string)$asset['asset_name'].' '.(string)($asset['serial_number']??'')),strtolower($query))));?>
