<?php if($section==='categories'&&$canManage):?><section class="card finance-filter-panel"><h2>New asset category</h2><p>Create simple equipment groups such as Computers, Printers, Furniture or Vehicles. Accounting controls are managed automatically.</p><form method="post" action="/office_app/public/assets-management/categories" class="finance-filter-form"><?=csrfField()?><div class="form-field"><label>Category code</label><input name="category_code" placeholder="e.g. COMPUTER" required></div><div class="form-field"><label>Category name</label><input name="category_name" placeholder="e.g. Computers" required></div><div class="form-field"><label>Expected life (months)</label><input name="useful_life_months" type="number" min="1" value="36" required></div><button class="btn btn-primary">Create category</button></form></section><?php endif;?>
