<?php if($section==='capitalization'&&$canCapitalize):?><section class="card finance-filter-panel"><h2>Capitalize inventory</h2><p>Issues available stock once, preserves source cost, and posts Inventory Asset → Fixed Asset reclassification.</p><form method="post" action="/office_app/public/assets-management/capitalize" class="finance-filter-form"><?=csrfField()?><div class="form-field"><label>Asset number</label><input name="asset_number" required></div><div class="form-field"><label>Asset name</label><input name="asset_name" required></div><div class="form-field"><label>Category</label><select name="asset_category_id" required><?php foreach($data['categories'] as $category):?><option value="<?=e($category['asset_category_id'])?>"><?=e($category['category_name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Source stock</label><select id="asset-stock" required><option value="">Select available stock</option><?php foreach($data['stock'] as $s):?><option value="<?=e($s['warehouse_id'].'|'.$s['location_id'].'|'.$s['product_id'])?>"><?=e($s['sku'].' · '.$s['product_name'].' · '.$s['warehouse_name'].'/'.$s['location_name'].' · available '.$s['available'])?></option><?php endforeach;?></select><input type="hidden" name="warehouse_id"><input type="hidden" name="location_id"><input type="hidden" name="product_id"></div><div class="form-field"><label>Quantity</label><input type="number" name="quantity" min="0.001" step="0.001" value="1" required></div><div class="form-field"><label>Acquisition date</label><input type="date" name="acquisition_date" value="<?=e(date('Y-m-d'))?>" required></div><div class="form-field"><label>Salvage value</label><input type="number" name="salvage_value" min="0" step="0.01" value="0"></div><div class="form-field"><label>Currency</label><input name="currency" value="<?=e($data['user']['company']['default_currency']??'ETB')?>" maxlength="3" required></div><div class="form-field"><label>Serial number</label><input name="serial_number"></div><button class="btn btn-primary">Capitalize selected stock</button></form></section><script>document.getElementById('asset-stock')?.addEventListener('change',e=>{const parts=e.target.value.split('|');['warehouse_id','location_id','product_id'].forEach((name,i)=>document.querySelector(`input[name="${name}"]`).value=parts[i]||'')});</script><?php endif;?></div>
